}

export async function recreateWithEnv(guest: Guest, o: RecreateOpts): Promise<RecreateResult> {
  const { container: c, unit } = o;
  const old = `${c}-old`;
  const fail = (note: string, rolledBack = false): RecreateResult => ({ status: "failed", note, rolledBack });

  // 0. Self-heal a half-finished earlier run (container missing, `-old` present).
  let insp = await inspect(guest, c);
  if (insp.code !== 0) {
    const oldInsp = await inspect(guest, old);
    if (oldInsp.code !== 0) return fail(`Could not find the "${c}" game container, so nothing was changed.`);
    const r = await guest.exec(`docker rename ${shq(old)} ${shq(c)}`);
    if (r.code !== 0) return fail(`Could not find the "${c}" game container, so nothing was changed.`);
    insp = await inspect(guest, c);
  }
  const cur = parseInspect(insp.stdout);
  if (!cur || !cur.image) return fail("Could not read the game container's settings, so nothing was changed.");

  // 1. Image defaults, so only user-set env is carried (and Entrypoint is only passed if overridden).
  let imgEnv = new Map<string, string>();
  let imgEntry: string[] | null | undefined;
  const ii = await guest.exec(`docker image inspect ${shq(cur.image)} --format '{{json .Config}}'`);
  if (ii.code === 0) {
    try {
      const cfg = JSON.parse(ii.stdout.trim());
      for (const e of (cfg.Env ?? []) as string[]) {
        const i = e.indexOf("=");
        if (i > 0) imgEnv.set(e.slice(0, i), e.slice(i + 1));
      }
      imgEntry = cfg.Entrypoint ?? null;
    } catch {
      imgEnv = new Map();
    }
  }

  // 2. Desired state + idempotent no-op.
  const wantEnv = new Map(cur.env);
  for (const [k, v] of Object.entries(o.env ?? {})) (v === null ? wantEnv.delete(k) : wantEnv.set(k, v));
  const wantCmd = o.cmd ? o.cmd(cur.cmd) : cur.cmd;
  const envSame = [...wantEnv].every(([k, v]) => cur.env.get(k) === v) && [...cur.env.keys()].every((k) => wantEnv.has(k));
  if (envSame && JSON.stringify(wantCmd) === JSON.stringify(cur.cmd)) return { status: "noop" };

  // 3. Build the create command from the OLD container's own config.
  const carried = [...wantEnv].filter(([k, v]) => imgEnv.get(k) !== v);
  const envText = carried.map(([k, v]) => `${k}=${v.replace(/\r?\n/g, " ")}`).join("\n") + (carried.length ? "\n" : "");
  const entryOverridden = !!cur.entrypoint && imgEntry !== undefined && JSON.stringify(cur.entrypoint) !== JSON.stringify(imgEntry);
  const cmdArgs = [...(entryOverridden ? cur.entrypoint!.slice(1) : []), ...wantCmd];
  const create = [
    `docker create --name ${shq(c)}`,
    ...Object.entries(cur.logOpts).map(([k, v]) => `--log-opt ${shq(`${k}=${v}`)}`),
    cur.user ? `--user ${shq(cur.user)}` : "",
    ...cur.ports.map((p) => `-p ${shq(p)}`),
    ...cur.binds.map((b) => `-v ${shq(b)}`),
    `--env-file ${shq(o.envFile)}`,
    entryOverridden ? `--entrypoint ${shq(cur.entrypoint![0])}` : "",
    shq(cur.image),
    ...cmdArgs.map(shq),
  ].filter(Boolean).join(" ");

  // 4. Swap. Everything from here on rolls back on failure.
  const wasActive = unit
    ? (await guest.exec(`systemctl is-active ${shq(unit)}`)).stdout.trim() === "active"
    : await isRunning(guest, c);
  const start = unit ? `systemctl start ${shq(unit)}` : `docker start ${shq(c)}`;
  const stop = unit ? `systemctl stop ${shq(unit)}` : `docker update --restart=no ${shq(c)} 2>/dev/null; docker stop ${shq(c)}`;

  let swapped = false;
  const cleanup = () => guest.exec(`rm -f ${shq(o.envFile)}`).catch(() => undefined);
  const rollback = async (): Promise<boolean> => {
    let ok = true;
    try {
      if (unit) await guest.exec(`systemctl stop ${shq(unit)}`, 120_000);
      if (swapped) {
        const r = await guest.exec(`docker rm -f ${shq(c)} >/dev/null 2>&1; docker rename ${shq(old)} ${shq(c)}`);
        ok = r.code === 0;
      }
      if (wasActive) ok = (await guest.exec(start, 120_000)).code === 0 && ok;
    } catch {
      ok = false;
    }
    await cleanup();
    return ok;
  };
  const failBack = async (why: string): Promise<RecreateResult> => {
    const ok = await rollback();
    return fail(
      ok ? `${why} Your previous configuration was restored.` : `${why} Restoring the previous container also failed — support has been alerted.`,
      ok,
    );
  };

  await guest.exec(`install -m 600 /dev/null ${shq(o.envFile)}`);
  await guest.writeFile(o.envFile, envText);
  const st = await guest.exec(stop, 120_000);
  if (st.code !== 0 || (await isRunning(guest, c))) {
    await cleanup();
    if (wasActive) await guest.exec(start, 120_000).catch(() => undefined);
    return fail("Could not stop the game cleanly, so nothing was changed.");
  }
  const rn = await guest.exec(`docker rm -f ${shq(old)} >/dev/null 2>&1; docker rename ${shq(c)} ${shq(old)}`);
  if (rn.code !== 0) {
    await cleanup();
    if (wasActive) await guest.exec(start, 120_000).catch(() => undefined);
    return fail("Could not replace the game container, so nothing was changed.");
  }
  swapped = true;
  const cr = await guest.exec(create, 120_000);
  await cleanup();
  if (cr.code !== 0) return failBack("Could not create the updated game container.");

  // 5. Start + wait.
  const notes: string[] = [];
  if (wasActive) {
    if ((await guest.exec(start, 120_000)).code !== 0) return failBack("The game did not start with the new settings.");
    const port = await o.waitPort();
    if (!(await isRunning(guest, c))) return failBack("The game did not come back up with the new settings.");
    if (port && !port.ok) notes.push("The game is running but wasn't answering yet when we checked — it may still be loading.");
  }

  // 6. Verify by reading the new container back.
  const after = parseInspect((await inspect(guest, c)).stdout);
  const envBad = !after || [...Object.entries(o.env ?? {})].some(([k, v]) => (v === null ? after.env.has(k) : after.env.get(k) !== v));
  const cmdBad = !after || JSON.stringify(after.cmd) !== JSON.stringify(wantCmd);
  const shapeBad = !after || JSON.stringify(after.binds) !== JSON.stringify(cur.binds) || JSON.stringify(after.ports) !== JSON.stringify(cur.ports);
  if (envBad || cmdBad) return failBack("Verification failed: the new container does not carry the new settings.");
  if (shapeBad) return failBack("Verification failed: the new container's ports or volumes differ from the old one.");

  await guest.exec(`docker rm -f ${shq(old)} >/dev/null 2>&1`);
  return { status: "recreated", wasActive, notes };
}
