import type { ApplierContext, Guest } from "./types";
import { shq } from "./types";

/**
 * Shared by the file-based "sim" appliers (eco, vintagestory, spaceengineers):
 * games that REWRITE their own config files while shutting down, so a patch made
 * while the game runs can be silently overwritten by the old in-memory values on
 * the next stop. The safe order is: stop -> patch -> start. If the game was not
 * running (customer stopped it) it is patched but NOT started.
 */

export type StopWriteResult =
  | { ok: true; restore(): Promise<void>; commit(): Promise<void> }
  | { ok: false; notes: string[] };

export type StopPatchOutcome = { ok: boolean; restarted: boolean; notes: string[] };

async function wasActiveNow(guest: Guest, unit: string | null, container: string): Promise<boolean> {
  if (unit) return (await guest.exec(`systemctl is-active ${shq(unit)}`)).stdout.trim() === "active";
  const r = await guest.exec(`docker inspect -f '{{.State.Running}}' ${shq(container)} 2>/dev/null`);
  return r.stdout.trim() === "true";
}

/**
 * Stop the game (when running), run `write`, start it again and wait for the port.
 * `write` must only change files and return restore/commit hooks; if the game then
 * fails to start, the files are restored and the game is started on the old config.
 */
export async function stopPatchStart(
  ctx: ApplierContext,
  container: string,
  write: () => Promise<StopWriteResult>,
): Promise<StopPatchOutcome> {
  const { guest, unit } = ctx;
  const active = await wasActiveNow(guest, unit, container);
  const stopCmd = unit ? `systemctl stop ${shq(unit)}` : `docker stop ${shq(container)}`;
  const startCmd = unit ? `systemctl start ${shq(unit)}` : `docker start ${shq(container)}`;
  const notes: string[] = [];

  if (active) {
    const st = await guest.exec(stopCmd, 180_000);
    if (st.code !== 0 || (await wasActiveNow(guest, unit, container))) {
      await guest.exec(startCmd, 120_000).catch(() => undefined);
      return { ok: false, restarted: false, notes: ["Could not stop the game cleanly, so nothing was changed."] };
    }
  }

  let res: StopWriteResult;
  try {
    res = await write();
  } catch (e) {
    res = { ok: false, notes: [`Writing the settings failed (${(e as Error).message.slice(0, 120)}). Nothing was changed.`] };
  }
  if (!res.ok) {
    if (active) await guest.exec(startCmd, 120_000).catch(() => undefined);
    return { ok: false, restarted: false, notes: res.notes };
  }

  if (active) {
    const s = await guest.exec(startCmd, 120_000);
    const port = s.code === 0 ? await ctx.waitPort() : null;
    const running = s.code === 0 && (await wasActiveNow(guest, unit, container));
    if (!running) {
      await res.restore().catch(() => undefined);
      await guest.exec(stopCmd, 120_000).catch(() => undefined);
      await guest.exec(startCmd, 120_000).catch(() => undefined);
      return { ok: false, restarted: false, notes: ["The game did not start with the new settings, so your previous settings were put back and the game was started again."] };
    }
    if (port && !port.ok) notes.push("The game is running but wasn't answering yet when we checked — it may still be loading.");
  }
  await res.commit().catch(() => undefined);
  return { ok: true, restarted: active, notes };
}

/** First line of `find` output, or null. Paths are shell-quoted. */
export async function findFile(guest: Guest, roots: string[], name: string, maxdepth: number): Promise<string | null> {
  for (const root of roots) {
    const r = await guest.exec(`find ${shq(root)} -maxdepth ${maxdepth} -type f -iname ${shq(name)} 2>/dev/null | head -1`);
    const p = r.stdout.trim().split("\n")[0]?.trim();
    if (r.code === 0 && p) return p;
  }
  return null;
}
