import type { GameConfigApplierSpec } from "../game-config-appliers";
import { shq } from "../game-config-shq";

/**
 * Mordhau (cm2network/mordhau) — PURE half. Read off the image's entry.sh + cfg
 * templates (CM2Walki/Mordhau): the game is launched with
 * `-GAMEINI=<appdir>/cfg/Game.ini -ENGINEINI=<appdir>/cfg/Engine.ini`, and the
 * SERVER_* env vars are substituted into `{{PLACEHOLDERS}}` in those two files
 * ONLY on a container's first launch and ONLY if cfg/Game.ini does not exist yet.
 * After that the files are the truth and the env vars are ignored. The setup
 * script bind-mounts /opt/mordhau over the image's own appdir, which hides the
 * cfg templates the image ships, so a real server may have no cfg files at all.
 * Hence: the applier (and the setup-script bake below) writes real files, never env.
 *
 *  Game.ini   [/Script/Mordhau.MordhauGameSession]  MaxSlots, ServerName, ServerPassword, AdminPassword
 *  Engine.ini [/Script/OnlineSubsystemUtils.IpNetDriver]  NetServerMaxTickRate
 * Both are read at server start -> every field needs a restart.
 */
export const MORDHAU_SPEC: GameConfigApplierSpec = {
  family: "mordhau",
  fields: {
    SERVER_NAME: { when: "restart" },
    SERVER_ADMINPW: { when: "restart", secret: true },
    SERVER_PW: { when: "restart", secret: true },
    SERVER_MAXPLAYERS: { when: "restart" },
    SERVER_TICKRATE: { when: "restart" },
  },
};

export const MORDHAU_DIR = "/opt/mordhau";
export const MORDHAU_GAME_INI = `${MORDHAU_DIR}/cfg/Game.ini`;
export const MORDHAU_ENGINE_INI = `${MORDHAU_DIR}/cfg/Engine.ini`;
export const MORDHAU_SESSION_SECTION = "/Script/Mordhau.MordhauGameSession";
export const MORDHAU_NET_SECTION = "/Script/OnlineSubsystemUtils.IpNetDriver";
export const MORDHAU_GAME_FIELDS = ["SERVER_NAME", "SERVER_ADMINPW", "SERVER_PW", "SERVER_MAXPLAYERS"] as const;
export const MORDHAU_ENGINE_FIELDS = ["SERVER_TICKRATE"] as const;

type V = Record<string, string | number | boolean | undefined>;

/** Game.ini key for each schema field. */
export function mordhauGameValues(values: V, only?: readonly string[]): Record<string, string> {
  const want = (k: string) => !only || only.includes(k);
  const out: Record<string, string> = {};
  if (want("SERVER_MAXPLAYERS")) out.MaxSlots = String(Math.min(64, Math.max(2, Math.trunc(Number(values.SERVER_MAXPLAYERS ?? 32)))));
  if (want("SERVER_NAME")) out.ServerName = String(values.SERVER_NAME ?? "").trim();
  if (want("SERVER_PW")) out.ServerPassword = String(values.SERVER_PW ?? "");
  if (want("SERVER_ADMINPW")) out.AdminPassword = String(values.SERVER_ADMINPW ?? "");
  return out;
}
export function mordhauTick(values: V): string {
  return String(Math.min(120, Math.max(20, Math.trunc(Number(values.SERVER_TICKRATE ?? 60)))));
}

/** The image's own cfg/Game.ini template (small real fixture), placeholders filled from values. */
export function mordhauGameIniTemplate(values: V): string {
  const g = mordhauGameValues(values);
  const maps = ["FFA_Contraband", "FFA_MountainPeak", "FFA_Taiga", "TDM_Contraband", "TDM_Taiga_64", "FFA_Camp", "TDM_ThePit", "FFA_Tourney", "TDM_Grad", "TDM_Taiga", "SKM_Grad", "SKM_Taiga", "SKM_ThePit", "TDM_Tourney", "FFA_ThePit", "TDM_Camp", "SKM_Tourney", "SKM_MountainPeak", "TDM_Camp_64", "SKM_Camp", "SKM_Contraband", "FFA_Grad", "TDM_MountainPeak"];
  return [
    "[/Script/Mordhau.MordhauGameMode]",
    "PlayerRespawnTime=5.000000",
    "BallistaRespawnTime=30.000000",
    "CatapultRespawnTime=30.000000",
    "HorseRespawnTime=30.000000",
    "DamageFactor=1.000000",
    "TeamDamageFactor=0.500000",
    ...maps.map((m) => `MapRotation=${m}`),
    "",
    `[${MORDHAU_SESSION_SECTION}]`,
    "bIsLANServer=False",
    `MaxSlots=${g.MaxSlots}`,
    `ServerName=${g.ServerName}`,
    `ServerPassword=${g.ServerPassword}`,
    `AdminPassword=${g.AdminPassword}`,
    "Admins=0",
    "BannedPlayers=()",
    "",
  ].join("\n");
}
export function mordhauEngineIniTemplate(values: V): string {
  return [
    "[/Script/EngineSettings.GameMapsSettings]",
    "ServerDefaultMap=/Game/Mordhau/Maps/ThePit/FFA_ThePit.FFA_ThePit",
    "",
    `[${MORDHAU_NET_SECTION}]`,
    `NetServerMaxTickRate=${mordhauTick(values)}`,
    "",
  ].join("\n");
}

/**
 * Fresh-install / reinstall survival: seed both ini files BEFORE the container's
 * first start (only when absent), so the game boots with the customer's values
 * and the image's first-launch sed (which only runs when Game.ini is missing)
 * never has to. Inserted right before `docker run -d --name mordhau`.
 */
export function applyMordhauSetup(setupScript: string, values: V | null | undefined): string {
  if (!values || !setupScript.includes("docker run -d --name mordhau")) return setupScript;
  const seed =
    `mkdir -p ${MORDHAU_DIR}/cfg && ` +
    `{ [ -f ${MORDHAU_GAME_INI} ] || printf '%s' ${shq(mordhauGameIniTemplate(values))} > ${MORDHAU_GAME_INI}; } && ` +
    `{ [ -f ${MORDHAU_ENGINE_INI} ] || printf '%s' ${shq(mordhauEngineIniTemplate(values))} > ${MORDHAU_ENGINE_INI}; } && ` +
    `chown -R 1000:1000 ${MORDHAU_DIR} && `;
  return setupScript.replace("docker run -d --name mordhau", () => `${seed}docker run -d --name mordhau`);
}
EOF
