import {
  MORDHAU_DIR, MORDHAU_ENGINE_FIELDS, MORDHAU_ENGINE_INI, MORDHAU_GAME_FIELDS, MORDHAU_GAME_INI, MORDHAU_NET_SECTION, MORDHAU_SESSION_SECTION, MORDHAU_SPEC,
  mordhauEngineIniTemplate, mordhauGameIniTemplate, mordhauGameValues, mordhauTick,
} from "../../lib/game-applier-specs/mordhau";
import type { ApplierContext, ApplyOutcome, Guest, GameConfigApplier } from "./types";
import { shq } from "./types";
import { patchRemoteFile } from "./kit/config-file";
import { patchIni, readIni } from "./kit/ini-patch";
import { verifyReadback } from "./kit/readback";

/**
 * Mordhau (cm2network/mordhau): Game.ini / Engine.ini under /opt/mordhau/cfg, read at server start.
 * The image only fills them from env on a first launch when Game.ini is absent, and the bind mount
 * hides the image's own cfg templates, so a missing file is CREATED from the image's template with
 * the customer's values (the game is launched with -GAMEINI/-ENGINEINI pointing here). Details:
 * lib/game-applier-specs/mordhau.ts. Everything needs a restart; this never restarts the game.
 */

type Step = { path: string; label: string; edits: { section: string; key: string; value: string }[]; template: () => string; fields: string[] };

const noNewline = (s: string) => !/[\r\n]/.test(s);

async function createFromTemplate(guest: Guest, path: string, content: string): Promise<boolean> {
  const dir = path.slice(0, path.lastIndexOf("/"));
  if ((await guest.exec(`mkdir -p ${shq(dir)} && chown 1000:1000 ${shq(dir)}`)).code !== 0) return false;
  await guest.writeFile(path, content);
  await guest.exec(`chown 1000:1000 ${shq(path)}`);
  return (await guest.readFile(path)) === content;
}

async function apply(ctx: ApplierContext): Promise<ApplyOutcome> {
  const { guest, values } = ctx;
  const gameFields = ctx.touched.filter((k) => (MORDHAU_GAME_FIELDS as readonly string[]).includes(k));
  const engineFields = ctx.touched.filter((k) => (MORDHAU_ENGINE_FIELDS as readonly string[]).includes(k));
  if ([values.SERVER_NAME, values.SERVER_PW, values.SERVER_ADMINPW].some((v) => !noNewline(String(v ?? "")))) {
    return { ok: false, applied: [], notes: ["Names and passwords can't contain line breaks. Nothing was changed on your server."] };
  }

  const steps: Step[] = [];
  if (gameFields.length) {
    const want = mordhauGameValues(values, gameFields);
    steps.push({
      path: MORDHAU_GAME_INI, label: "Game.ini", fields: gameFields, template: () => mordhauGameIniTemplate(values),
      edits: Object.entries(want).map(([key, value]) => ({ section: MORDHAU_SESSION_SECTION, key, value })),
    });
  }
  if (engineFields.length) {
    steps.push({
      path: MORDHAU_ENGINE_INI, label: "Engine.ini", fields: engineFields, template: () => mordhauEngineIniTemplate(values),
      edits: [{ section: MORDHAU_NET_SECTION, key: "NetServerMaxTickRate", value: mordhauTick(values) }],
    });
  }

