import type { GameConfigApplierSpec } from "../game-config-appliers";

/**
 * Vintage Story (ich777/vintagestory) — PURE half. The image runs
 * `VintagestoryServer --dataPath /vintagestory/data` with the host folder
 * /opt/vintagestory mounted at /vintagestory (verified live 2026-09-30 by the
 * mod installer, worker/game-mods.ts), so the server's own config is
 * /opt/vintagestory/data/serverconfig.json. Its top-level keys are the game's
 * ServerConfig properties and the schema keys ARE those names: ServerName,
 * MaxClients, Password, AdvertiseServer, WelcomeMessage. The image has no env
 * vars for any of them (only UID/GID/VS_CHANNEL).
 *
 * The game keeps its config in memory and writes serverconfig.json back when it
 * shuts down, so a patch made while it runs would be overwritten by the old
 * values. The applier therefore does stop -> patch -> start (like a recreate:
 * a brief restart is part of the apply); a server the customer stopped is
 * patched and left stopped.
 */
export const VINTAGESTORY_SPEC: GameConfigApplierSpec = {
  family: "vintagestory",
  fields: {
    ServerName: { when: "recreate", note: "Written to serverconfig.json with the game stopped, then the game starts again (brief restart)." },
    MaxClients: { when: "recreate", note: "Written to serverconfig.json with the game stopped, then the game starts again (brief restart)." },
    Password: { when: "recreate", secret: true, note: "Written to serverconfig.json with the game stopped, then the game starts again (brief restart). Blank = open server." },
    AdvertiseServer: { when: "recreate", note: "Written to serverconfig.json with the game stopped, then the game starts again (brief restart)." },
    WelcomeMessage: { when: "recreate", note: "Written to serverconfig.json with the game stopped, then the game starts again (brief restart)." },
  },
};

export const VINTAGESTORY_CONTAINER = "vintagestory";
export const VINTAGESTORY_CONFIG = "/opt/vintagestory/data/serverconfig.json";

type V = Record<string, string | number | boolean | undefined>;

/** serverconfig.json value per touched schema key. A blank password is null (the game's own "no password"). */
export function vintagestoryValues(values: V, only: readonly string[]): Record<string, string | number | boolean | null> {
  const out: Record<string, string | number | boolean | null> = {};
  if (only.includes("ServerName")) out.ServerName = String(values.ServerName ?? "").trim();
  if (only.includes("MaxClients")) out.MaxClients = Math.min(64, Math.max(1, Math.trunc(Number(values.MaxClients ?? 16))));
  if (only.includes("Password")) { const p = String(values.Password ?? ""); out.Password = p === "" ? null : p; }
  if (only.includes("AdvertiseServer")) out.AdvertiseServer = values.AdvertiseServer === true;
  if (only.includes("WelcomeMessage")) out.WelcomeMessage = String(values.WelcomeMessage ?? "");
  return out;
}
