import { VINTAGESTORY_CONFIG, VINTAGESTORY_CONTAINER, VINTAGESTORY_SPEC, vintagestoryValues } from "../../lib/game-applier-specs/vintagestory";
import type { ApplierContext, ApplyOutcome, GameConfigApplier } from "./types";
import { patchRemoteFile } from "./kit/config-file";
import { patchJson, readJson } from "./kit/json-patch";
import { verifyReadback } from "./kit/readback";
import { stopPatchStart } from "./sim-common";

/** Vintage Story: serverconfig.json, stop -> patch -> start (the game rewrites it on shutdown). See the spec file. */
function validate(content: string): string | null {
  try {
    const d = JSON.parse(content);
    return d && typeof d === "object" && !Array.isArray(d) ? null : "The result is not a JSON object.";
  } catch {
    return "The result is not valid JSON.";
  }
}

async function apply(ctx: ApplierContext): Promise<ApplyOutcome> {
  const { guest } = ctx;
  const want = vintagestoryValues(ctx.values, ctx.touched);
  const edits = Object.entries(want).map(([k, v]) => ({ path: [k], value: v }));
  const old = await guest.readFile(VINTAGESTORY_CONFIG);
  if (old === null) {
    return { ok: true, applied: [], notes: ["Vintage Story hasn't created its serverconfig.json yet (the server has never fully started), so these settings were saved but not applied. Start the server once, then save again."] };
  }
  try {
    if (patchJson(old, edits) === old) return { ok: true, applied: [], notes: ["The server's config already matched — nothing to change."] };
  } catch {
    return { ok: false, applied: [], notes: ["serverconfig.json could not be parsed, so it was left untouched. Nothing was changed on your server."] };
  }

  let kept = false;
  const out = await stopPatchStart(ctx, VINTAGESTORY_CONTAINER, async () => {
    const res = await patchRemoteFile(guest, { path: VINTAGESTORY_CONFIG, patch: (o) => patchJson(o, edits), validate });
    if (res.status === "invalid" || res.status === "failed") return { ok: false, notes: [res.reason, "Nothing was changed on your server."] };
    if (res.status !== "changed") { kept = true; return { ok: true, restore: async () => undefined, commit: async () => undefined }; }
    const back = (await guest.readFile(VINTAGESTORY_CONFIG)) ?? "";
    const actual: Record<string, unknown> = {};
    for (const k of Object.keys(want)) actual[k] = readJson(back, [k]);
    const rb = verifyReadback(want, actual);
    if (!rb.ok) {
      await res.restore();
      return { ok: false, notes: [`Verification failed for ${rb.mismatched.join(", ")}; the previous config was restored. Nothing was changed on your server.`] };
    }
    return { ok: true, restore: res.restore, commit: res.commit };
  });
  if (!out.ok) return { ok: false, applied: [], notes: out.notes };
  void kept;
  const notes = [...out.notes];
  notes.push(out.restarted ? "Your server restarted briefly to apply this — connected players were disconnected and can rejoin now." : "Your server is stopped; the new settings will be used the next time you start it.");
  return { ok: true, applied: [`Updated Vintage Story's serverconfig.json (${ctx.touched.join(", ")}).`], notes, restarted: out.restarted };
}

export const vintagestoryApplier: GameConfigApplier = { spec: VINTAGESTORY_SPEC, apply };
