 * are only used when a game (save) is created; they cannot change an existing world,
 * and we have not confirmed the exact accepted value format for Mode, so we do not write it.
 */
export const EMPYRION_SPEC: GameConfigApplierSpec = {
  family: "empyrion",
  fields: {
    serverName: { when: "restart" },
    serverPassword: { when: "restart", secret: true },
    maxPlayers: { when: "restart" },
  },
};

export const EMPYRION_ROOT = "/opt/empyrion";

type V = Record<string, string | number | boolean | undefined>;
export type YamlEdit = { key: string; value: string | number };

/** dedicated.yaml key per touched schema field. */
export function empyrionValues(values: V, only: readonly string[]): Record<string, string | number> {
  const out: Record<string, string | number> = {};
  if (only.includes("serverName")) out.Srv_Name = String(values.serverName ?? "").trim();
  if (only.includes("serverPassword")) out.Srv_Password = String(values.serverPassword ?? "");
  if (only.includes("maxPlayers")) out.Srv_MaxPlayers = Math.min(60, Math.max(1, Math.trunc(Number(values.maxPlayers ?? 16))));
  return out;
}

const keyLine = (key: string) => new RegExp(`^(\\s*)${key}:(\\s*)(.*)$`);

/** Split a YAML scalar remainder into [scalar text, trailing comment incl. leading space]. */
function splitScalar(rest: string): [string, string] {
  const q = rest[0];
  if (q === '"' || q === "'") {
    for (let i = 1; i < rest.length; i++) {
      if (q === '"' && rest[i] === "\\") { i++; continue; }
      if (rest[i] === q) return [rest.slice(0, i + 1), rest.slice(i + 1)];
    }
    return [rest, ""];
  }
  const m = /\s+#/.exec(rest);
  return m ? [rest.slice(0, m.index), rest.slice(m.index)] : [rest.trimEnd(), ""];
}

const yamlString = (s: string) => `"${s.replace(/\\/g, "\\\\").replace(/"/g, '\\"')}"`;

/** Set scalar values of existing `Key: value` lines, preserving everything else (comments, indent, line endings). Throws when a key is absent. */
export function patchYamlScalars(content: string, edits: YamlEdit[]): string {
  const eol = content.includes("\r\n") ? "\r\n" : "\n";
  const lines = content.split(/\r?\n/);
  for (const e of edits) {
    const re = keyLine(e.key);
    const i = lines.findIndex((l) => re.test(l) && !/^\s*#/.test(l));
    if (i < 0) throw new Error(`missing key ${e.key}`);
    const m = re.exec(lines[i])!;
    const [, tail] = splitScalar(m[3]);
    lines[i] = `${m[1]}${e.key}: ${typeof e.value === "number" ? String(e.value) : yamlString(e.value)}${tail}`;
  }
  return lines.join(eol);
}

/** Read one scalar (unquoted); undefined if absent. */
export function readYamlScalar(content: string, key: string): string | undefined {
  const re = keyLine(key);
  for (const l of content.split(/\r?\n/)) {
    if (/^\s*#/.test(l)) continue;
    const m = re.exec(l);
    if (!m) continue;
    const [s] = splitScalar(m[3]);
    if (s.startsWith('"')) return s.slice(1, -1).replace(/\\(["\\])/g, "$1");
    if (s.startsWith("'")) return s.slice(1, -1).replace(/''/g, "'");
    return s;
  }
  return undefined;
}

export function yamlHasKey(content: string, key: string): boolean {
  return readYamlScalar(content, key) !== undefined;
}
