import type { GameConfigApplierSpec } from "../game-config-appliers";

/**
 * Space Engineers (mmmaxwwwell/space-engineers-dedicated-docker-linux, Wine) — PURE half.
 * 100% XML files, no env vars. On the guest (setup script volumes):
 *   /opt/spaceengineers/SpaceEngineersDedicated  -> the server dir, holding SpaceEngineers-Dedicated.cfg
 *   /opt/spaceengineers/World                    -> the loaded world (Sandbox.sbc, Sandbox_config.sbc, ...)
 * Element names are the game's own (MyObjectBuilder_SessionSettings):
 *   <ServerName> (top level of the .cfg) and, for the session fields, <GameMode> <MaxPlayers> <OnlineMode>
 *   <EnvironmentHostility> <AutoSaveInMinutes> <TotalPCU> inside <SessionSettings> of the .cfg and
 *   inside <Settings> of the world's Sandbox_config.sbc. Space Engineers takes session settings from the
 *   world it loads once one exists, so the applier updates BOTH files wherever the element exists.
 *   It never ADDS a missing element (the XML serializer's element order matters).
 *
 * worldName is NOT mapped: <WorldName> only names a world that is being created; the running
 * world is chosen by <LoadWorld>, which the image maintains itself.
 *
 * The game writes its files while shutting down, so the applier does stop -> patch -> start
 * (brief restart); a server the customer stopped is patched and left stopped.
 */
const NOTE = "Written to the game's XML config (and the loaded world's settings file) with the game stopped, then the game starts again (brief restart). Only existing elements are changed.";
export const SPACEENGINEERS_SPEC: GameConfigApplierSpec = {
  family: "spaceengineers",
  fields: {
    serverName: { when: "recreate", note: NOTE },
    gameMode: { when: "recreate", note: NOTE },
    maxPlayers: { when: "recreate", note: NOTE },
    onlineMode: { when: "recreate", note: NOTE },
    environmentHostility: { when: "recreate", note: NOTE },
    autoSaveInMinutes: { when: "recreate", note: NOTE },
    totalPCU: { when: "recreate", note: NOTE },
  },
};

export const SE_CONTAINER = "spaceengineers";
export const SE_CFG = "/opt/spaceengineers/SpaceEngineersDedicated/SpaceEngineers-Dedicated.cfg";
export const SE_WORLD_CONFIG = "/opt/spaceengineers/World/Sandbox_config.sbc";
export const SE_SESSION_TAGS: Record<string, string> = {
  gameMode: "GameMode", maxPlayers: "MaxPlayers", onlineMode: "OnlineMode",
  environmentHostility: "EnvironmentHostility", autoSaveInMinutes: "AutoSaveInMinutes", totalPCU: "TotalPCU",
};

type V = Record<string, string | number | boolean | undefined>;

const clampInt = (v: unknown, lo: number, hi: number, d: number) => Math.min(hi, Math.max(lo, Math.trunc(Number(v ?? d))));

/** XML element name -> text for the touched session fields. */
export function seSessionValues(values: V, only: readonly string[]): Record<string, string> {
  const out: Record<string, string> = {};
  for (const [field, tag] of Object.entries(SE_SESSION_TAGS)) {
    if (!only.includes(field)) continue;
    if (field === "maxPlayers") out[tag] = String(clampInt(values.maxPlayers, 1, 32, 16));
    else if (field === "autoSaveInMinutes") out[tag] = String(clampInt(values.autoSaveInMinutes, 1, 60, 5));
    else if (field === "totalPCU") out[tag] = String(clampInt(values.totalPCU, 100000, 5000000, 1000000));
    else out[tag] = String(values[field] ?? "");
  }
  return out;
}

export const xmlEscape = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
const xmlUnescape = (s: string) => s.replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&amp;/g, "&");

function elementRe(tag: string): RegExp {
  return new RegExp(`<${tag}(\\s[^>]*)?>([\\s\\S]*?)</${tag}>|<${tag}(\\s[^>]*)?/>`);
