import {
  SEG_PLACEHOLDER, SE_CFG, SE_CONTAINER, SE_SESSION_TAGS, SE_WORLD_CONFIG, SPACEENGINEERS_SPEC, seSessionValues, xmlGetElement, xmlProblem, xmlSetElement,
} from "../../lib/game-applier-specs/spaceengineers";
import type { ApplierContext, ApplyOutcome, GameConfigApplier } from "./types";
import { patchRemoteFile } from "./kit/config-file";
import { verifyReadback } from "./kit/readback";
import { findFile, stopPatchStart } from "./sim-common";

/**
 * Space Engineers: SpaceEngineers-Dedicated.cfg (<ServerName>, <SessionSettings>) and the loaded world's
 * Sandbox_config.sbc (<Settings>), stop -> patch -> start. Only existing XML elements are changed.
 * See lib/game-applier-specs/spaceengineers.ts.
 */
type Edit = { tag: string; value: string; scope?: string };
type FileJob = { path: string; label: string; edits: Edit[] };

function applyEdits(xml: string, edits: Edit[]): { out: string; applied: string[]; skipped: string[] } {
  let out = xml;
  const applied: string[] = [];
  const skipped: string[] = [];
  for (const e of edits) {
    const next = xmlSetElement(out, e.tag, e.value, e.scope);
    if (next === null) skipped.push(e.tag);
    else { out = next; applied.push(e.tag); }
  }
  return { out, applied, skipped };
}

async function apply(ctx: ApplierContext): Promise<ApplyOutcome> {
  const { guest } = ctx;
  const session = seSessionValues(ctx.values, ctx.touched);
  const nameEdit: Edit[] = ctx.touched.includes("serverName") ? [{ tag: "ServerName", value: String(ctx.values.serverName ?? "").trim() }] : [];

  const cfgPath = (await guest.readFile(SE_CFG)) !== null ? SE_CFG : await findFile(guest, ["/opt/spaceengineers/SpaceEngineersDedicated"], "SpaceEngineers-Dedicated.cfg", 3);
  const worldPath = (await guest.readFile(SE_WORLD_CONFIG)) !== null ? SE_WORLD_CONFIG : await findFile(guest, ["/opt/spaceengineers/World"], "Sandbox_config.sbc", 2);

  const jobs: FileJob[] = [];
  if (cfgPath) jobs.push({ path: cfgPath, label: "SpaceEngineers-Dedicated.cfg", edits: [...nameEdit, ...Object.entries(session).map(([tag, value]) => ({ tag, value, scope: "SessionSettings" }))] });
  if (worldPath && Object.keys(session).length) jobs.push({ path: worldPath, label: "the world's Sandbox_config.sbc", edits: Object.entries(session).map(([tag, value]) => ({ tag, value, scope: "Settings" })) });
  if (!jobs.length) {
    return { ok: true, applied: [], notes: ["Space Engineers hasn't created its config files yet (the server has never fully started), so these settings were saved but not applied. Start the server once, then save again."] };
  }

  // Plan without touching anything: which elements exist, would anything change?
  let anyChange = false;
  const covered = new Set<string>();
  for (const j of jobs) {
    const old = await guest.readFile(j.path);
    if (old === null) continue;
    const r = applyEdits(old, j.edits);
    if (xmlProblem(old)) return { ok: false, applied: [], notes: [`${j.label} is not well-formed XML, so it was left untouched. Nothing was changed on your server.`] };
    if (r.out !== old) anyChange = true;
    r.applied.forEach((t) => covered.add(t));
  }
  const wantedTags = [...nameEdit.map((e) => e.tag), ...Object.keys(session)];
  const notFound = wantedTags.filter((t) => !covered.has(t));
  const notes: string[] = [];
  if (notFound.length) notes.push(`These settings weren't found in the game's config files, so they were saved but not applied: ${notFound.join(", ")}.`);
  if (!anyChange) return { ok: true, applied: [], notes: [...notes, "The game's config already matched — nothing to change."] };

  const out = await stopPatchStart(ctx, SE_CONTAINER, async () => {
    const undo: (() => Promise<void>)[] = [];
    const commits: (() => Promise<void>)[] = [];
    const rollback = async () => { for (const u of undo.reverse()) await u().catch(() => undefined); };
    for (const j of jobs) {
      const res = await patchRemoteFile(guest, { path: j.path, patch: (o) => applyEdits(o, j.edits).out, validate: xmlProblem });
      if (res.status === "invalid" || res.status === "failed") { await rollback(); return { ok: false as const, notes: [res.reason, "Nothing was changed on your server."] }; }
      if (res.status !== "changed") continue;
      undo.push(res.restore);
      commits.push(res.commit);
      const back = (await guest.readFile(j.path)) ?? "";
      const expected: Record<string, unknown> = {};
      const actual: Record<string, unknown> = {};
      for (const e of j.edits) if (xmlGetElement(back, e.tag, e.scope) !== undefined) { expected[e.tag] = e.value; actual[e.tag] = xmlGetElement(back, e.tag, e.scope); }
      const rb = verifyReadback(expected, actual);
      if (!rb.ok) { await rollback(); return { ok: false as const, notes: [`Verification failed for ${rb.mismatched.join(", ")}; the previous files were restored. Nothing was changed on your server.`] }; }
    }
    return { ok: true as const, restore: rollback, commit: async () => { for (const c of commits) await c(); } };
  });
  if (!out.ok) return { ok: false, applied: [], notes: out.notes };
  notes.push(...out.notes);
  notes.push(out.restarted ? "Your server restarted briefly to apply this — connected players were disconnected and can rejoin now." : "Your server is stopped; the new settings will be used the next time you start it.");
  return { ok: true, applied: [`Updated Space Engineers' config (${wantedTags.filter((t) => covered.has(t)).join(", ")}).`], notes, restarted: out.restarted };
}

export const spaceengineersApplier: GameConfigApplier = { spec: SPACEENGINEERS_SPEC, apply };
void SE_SESSION_TAGS;
EOF
