import { test } from "node:test";
import assert from "node:assert/strict";
import { runApplier } from "../worker/game-config-appliers/run";
import type { Guest, GameConfigApplier } from "../worker/game-config-appliers/types";
import { squadApplier } from "../worker/game-config-appliers/squad";
import { mordhauApplier } from "../worker/game-config-appliers/mordhau";
import { vintagestoryApplier } from "../worker/game-config-appliers/vintagestory";
import { ecoApplier } from "../worker/game-config-appliers/eco";
import { empyrionApplier } from "../worker/game-config-appliers/empyrion";
import { spaceengineersApplier } from "../worker/game-config-appliers/spaceengineers";
import { getApplier } from "../worker/game-config-appliers";
import { SQUAD_SPEC, applySquadSetup, squadMods } from "../lib/game-applier-specs/squad";
import { MORDHAU_GAME_INI, MORDHAU_ENGINE_INI, MORDHAU_SPEC, applyMordhauSetup, mordhauGameIniTemplate } from "../lib/game-applier-specs/mordhau";
import { VINTAGESTORY_CONFIG, VINTAGESTORY_SPEC } from "../lib/game-applier-specs/vintagestory";
import { ECO_NETWORK_CONFIG, ECO_SPEC } from "../lib/game-applier-specs/eco";
import { EMPYRION_SPEC, patchYamlScalars, readYamlScalar } from "../lib/game-applier-specs/empyrion";
import { SE_CFG, SE_WORLD_CONFIG, SPACEENGINEERS_SPEC, xmlGetElement, xmlProblem, xmlSetElement } from "../lib/game-applier-specs/spaceengineers";
import { GAME_CONFIG_SCHEMAS, validateConfig, canApplyConfig, fieldApplyInfo } from "../lib/game-config";
import { buildGameSetupScript } from "../worker/game-variant";
import { fakeGuest } from "./_fake-docker-guest";

type Vals = Record<string, string | number | boolean>;
const defaults = (family: string, over: Vals = {}): Vals => {
  const v = validateConfig(family, { SERVER_ADMINPW: "adminpw-1", ...over }) as { ok: boolean; values: Vals };
  assert.ok(v.ok, `${family} defaults validate`);
  return v.values;
};

/** The shared fake, re-pointed at a family's container, with the few extra shell commands the sim appliers use. */
function guestFor(container: string, o: { image: string; env?: string[]; cmd?: string[]; binds?: string[]; files?: Record<string, string>; active?: boolean; find?: Record<string, string> }) {
  const g = fakeGuest({ container, unit: `${container}.service`, files: o.files, active: o.active });
  const c = g.containers.get(container)!;
  c.image = o.image;
  c.env = ["PATH=/usr/bin", "DOTNET=9", ...(o.env ?? [])];
  c.cmd = o.cmd ?? [];
  c.binds = o.binds ?? [];
  c.ports = {};
  const inner = g.guest;
  const guest: Guest = {
    async exec(cmd, t) {
      if (/^mkdir -p .* && chown /.test(cmd) || /^chown /.test(cmd)) return { code: 0, stdout: "", stderr: "" };
      const f = /^find '([^']+)' .*-iname '([^']+)'/.exec(cmd);
      if (f) {
        const hit = [...g.files.keys()].find((p) => p.startsWith(f[1] + "/") && p.toLowerCase().endsWith("/" + f[2].toLowerCase()));
        return { code: 0, stdout: hit ? hit + "\n" : "", stderr: "" };
      }
      return inner.exec(cmd, t);
    },
    readFile: (p) => inner.readFile(p),
    writeFile: (p, c) => inner.writeFile(p, c),
  };
  return { ...g, guest };
}

function run(applier: GameConfigApplier, g: ReturnType<typeof guestFor>, values: Vals, changed: string[] | undefined) {
  return runApplier(applier, { server: { id: "s1" }, values, changed, restartRequested: false, guest: g.guest, unit: g.unit, waitPort: async () => ({ ok: true }) });
}
const all = (out: { applied: string[]; notes: string[] }) => [...out.applied, ...out.notes].join(" ");

test("registered in both lists and every mapped key exists in the schema", () => {
  for (const [fam, spec] of Object.entries({ squad: SQUAD_SPEC, mordhau: MORDHAU_SPEC, vintagestory: VINTAGESTORY_SPEC, eco: ECO_SPEC, empyrion: EMPYRION_SPEC, spaceengineers: SPACEENGINEERS_SPEC })) {
    assert.ok(getApplier(fam), fam);
    assert.ok(canApplyConfig(fam), fam);
    const keys = GAME_CONFIG_SCHEMAS[fam].fields.map((f) => f.key);
    for (const k of Object.keys(spec.fields)) assert.ok(keys.includes(k), `${fam}.${k}`);
    for (const k of keys.filter((x) => !(x in spec.fields))) assert.equal(fieldApplyInfo(fam, k)?.when ?? null, null, `${fam}.${k} is saved only`);
  }
});

// ---------------------------------------------------------------- squad
const SQUAD_G = () => guestFor("squad", {
  image: "cm2network/squad:latest",
  env: ["SERVER_NAME=Nxeon Squad", "FIXEDMAXPLAYERS=50", "PORT=7787", "MODS=()"],
  binds: ["/opt/squad:/home/steam/squad-dedicated"],
});
test("squad: name, player limit and mods are applied through a recreate; unchanged volumes kept", async () => {
  for (const [field, value, key, expected] of [["SERVER_NAME", "My Squad", "SERVER_NAME", "My Squad"], ["FIXEDMAXPLAYERS", 80, "FIXEDMAXPLAYERS", "80"], ["MODS", "(111 222)", "MODS", "(111 222)"], ["MODS", "111,222", "MODS", "(111 222)"]] as const) {
    const g = SQUAD_G();
    const out = await run(squadApplier, g, defaults("squad", { [field]: value }), [field]);
    assert.equal(out.ok, true, `${field}: ${all(out)}`);
    const c = g.containers.get("squad")!;
    assert.ok(c.env.includes(`${key}=${expected}`), `${field} -> ${c.env.join()}`);
    assert.deepEqual(c.binds, ["/opt/squad:/home/steam/squad-dedicated"]);
    assert.equal(out.restarted, true);
    assert.equal(c.running, true);
  }
});
test("squad: re-applying the same values is a no-op", async () => {
  const g = SQUAD_G();
  const out = await run(squadApplier, g, defaults("squad", { SERVER_NAME: "Nxeon Squad", FIXEDMAXPLAYERS: 50 }), ["SERVER_NAME", "FIXEDMAXPLAYERS"]);
  assert.equal(out.ok, true);
  assert.equal(g.st.created, 0);
  assert.match(all(out), /nothing to change/);
});
test("squad: a name the image's sed cannot take is refused before anything happens; bad mod ids too", async () => {
  for (const bad of ["a/b", "a&b", 'a"b', "a\\b"]) {
    const g = SQUAD_G();
    const out = await run(squadApplier, g, defaults("squad", { SERVER_NAME: bad }), ["SERVER_NAME"]);
    assert.equal(out.ok, false, bad);
    assert.equal(g.st.created, 0);
  }
  const g = SQUAD_G();
  assert.equal((await run(squadApplier, g, defaults("squad", { MODS: "(abc)" }), ["MODS"])).ok, false);
  assert.equal(squadMods("(1 2)"), "(1 2)");
  assert.equal(squadMods(""), "()");
});
test("squad: stopped server is rebuilt but not started; failed create rolls back to the old container", async () => {
  const g = guestFor("squad", { image: "cm2network/squad:latest", env: ["SERVER_NAME=Nxeon Squad"], active: false });
  const out = await run(squadApplier, g, defaults("squad", { SERVER_NAME: "Other" }), ["SERVER_NAME"]);
