});
test("squad: bake into the setup script (MODS added, absent when blank) and name/slots through the real build", () => {
  const raw = "docker run -d --name squad --restart unless-stopped -e SERVER_NAME='Nxeon Squad' -e FIXEDMAXPLAYERS='50' -v /opt/squad:/home/steam/squad-dedicated cm2network/squad:latest";
  assert.match(applySquadSetup(raw, { MODS: "(5 6)" }), /-e MODS='\(5 6\)' -v \/opt\/squad:/);
  assert.equal(applySquadSetup(raw, { MODS: "" }), raw);
  const script = buildGameSetupScript({ id: "s", osTemplate: { setupScript: raw, family: "squad" }, gameConfig: { SERVER_NAME: "Big Squad", FIXEDMAXPLAYERS: 64, MODS: "(7)" } })!;
  assert.match(script, /SERVER_NAME='Big Squad'/);
  assert.match(script, /FIXEDMAXPLAYERS='64'/);
  assert.match(script, /MODS='\(7\)'/);
});

// ---------------------------------------------------------------- mordhau
const GAME_INI = `[/Script/Mordhau.MordhauGameMode]
PlayerRespawnTime=5.000000
