test("squad: name, player limit and mods are applied through a recreate; unchanged volumes kept", async () => {
  for (const [field, value, key, expected] of [["SERVER_NAME", "My Squad", "SERVER_NAME", "My Squad"], ["FIXEDMAXPLAYERS", 80, "FIXEDMAXPLAYERS", "80"], ["MODS", "(111 222)", "MODS", "(111 222)"], ["MODS", "111,222", "MODS", "(111 222)"]] as const) {
    const g = SQUAD_G();
    const out = await run(squadApplier, g, defaults("squad", { [field]: value }), [field]);
    assert.equal(out.ok, true, `${field}: ${all(out)}`);
    const c = g.containers.get("squad")!;
