    assert.deepEqual(c.binds, ["/opt/squad:/home/steam/squad-dedicated"]);
    assert.equal(out.restarted, true);
    assert.equal(c.running, true);
  }
});
test("squad: re-applying the same values is a no-op", async () => {
  const g = SQUAD_G();
