  assert.ok(!text.includes("Sup3r-Secret") && !text.includes("Pass-Word-9"));
  assert.ok(!g.log.some((l) => (l.includes("Sup3r-Secret") || l.includes("Pass-Word-9")) && !l.startsWith("write ")));
