test("vintagestory: stopped server is patched and left stopped; no-op when unchanged; missing file is an honest note", async () => {
  const g = VS_G(false);
  const out = await run(vintagestoryApplier, g, defaults("vintagestory", { MaxClients: 30 }), ["MaxClients"]);
  assert.equal(out.ok, true);
  assert.equal(vs(g).MaxClients, 30);
  assert.equal(g.containers.get("vintagestory")!.running, false);
  assert.ok(!g.log.some((l) => l.startsWith("systemctl start")));
  const g2 = VS_G();
  const same = await run(vintagestoryApplier, g2, defaults("vintagestory", { MaxClients: 16 }), ["MaxClients"]);
  assert.match(all(same), /already matched/);
  assert.ok(!g2.log.some((l) => l.startsWith("systemctl stop")), "no needless restart");
  const g3 = VS_G(true, {});
  const miss = await run(vintagestoryApplier, g3, defaults("vintagestory", { MaxClients: 30 }), ["MaxClients"]);
  assert.equal(miss.ok, true);
  assert.match(all(miss), /Start the server once/);
});
test("vintagestory: invalid JSON on disk or a corrupted write leaves the file untouched and the game running", async () => {
  const g = VS_G(true, { [VINTAGESTORY_CONFIG]: "{ nope" });
  const out = await run(vintagestoryApplier, g, defaults("vintagestory", { MaxClients: 30 }), ["MaxClients"]);
  assert.equal(out.ok, false);
  assert.equal(g.files.get(VINTAGESTORY_CONFIG), "{ nope");
  assert.equal(g.containers.get("vintagestory")!.running, true);
  const g2 = fakeGuest({ container: "vintagestory", unit: "vintagestory.service", files: { [VINTAGESTORY_CONFIG]: VS_JSON }, corruptWrite: VINTAGESTORY_CONFIG });
  const out2 = await runApplier(vintagestoryApplier, { server: { id: "s" }, values: defaults("vintagestory", { MaxClients: 30 }), changed: ["MaxClients"], restartRequested: false, guest: g2.guest, unit: g2.unit, waitPort: async () => ({ ok: true }) });
  assert.equal(out2.ok, false);
  assert.equal(g2.files.get(VINTAGESTORY_CONFIG), VS_JSON);
  assert.equal(g2.containers.get("vintagestory")!.running, true, "game started again on the old config");
});
test("vintagestory: if the game won't start after the patch, the old config is restored", async () => {
  const g = fakeGuest({ container: "vintagestory", unit: "vintagestory.service", files: { [VINTAGESTORY_CONFIG]: VS_JSON } });
  let starts = 0;
  const wrapped: Guest = { ...g.guest, exec: async (cmd, t) => (cmd.startsWith("systemctl start") && starts++ === 0 ? { code: 1, stdout: "", stderr: "x" } : g.guest.exec(cmd, t)) };
  const out = await runApplier(vintagestoryApplier, { server: { id: "s" }, values: defaults("vintagestory", { MaxClients: 30 }), changed: ["MaxClients"], restartRequested: false, guest: wrapped, unit: g.unit, waitPort: async () => ({ ok: true }) });
  assert.equal(out.ok, false);
  assert.equal(g.files.get(VINTAGESTORY_CONFIG), VS_JSON);
  assert.equal(g.containers.get("vintagestory")!.running, true);
});

