  assert.match(all(same), /already matched/);
  const g2 = guestFor("empyrion", { image: "bitr/empyrion-server:latest", files: { [EMP_PATH]: "ServerConfig:\n  Srv_Name: x\n" } });
  assert.equal((await run(empyrionApplier, g2, defaults("empyrion", { maxPlayers: 5 }), ["maxPlayers"])).ok, false);
  const g3 = guestFor("empyrion", { image: "bitr/empyrion-server:latest", files: {} });
  assert.match(all(await run(empyrionApplier, g3, defaults("empyrion", { maxPlayers: 5 }), ["maxPlayers"])), /Start the server once/);
  assert.equal(patchYamlScalars("A:\n  Srv_Name: 'q'  # c\n", [{ key: "Srv_Name", value: "n" }]), 'A:\n  Srv_Name: "n"  # c\n');
});

// ---------------------------------------------------------------- space engineers
const SE_CFG_XML = `<?xml version="1.0"?>
<MyConfigDedicated xmlns:xsd="http://www.w3.org/2001/XMLSchema">
  <SessionSettings>
    <GameMode>Survival</GameMode>
    <MaxPlayers>16</MaxPlayers>
    <OnlineMode>PUBLIC</OnlineMode>
    <EnvironmentHostility>NORMAL</EnvironmentHostility>
    <AutoSaveInMinutes>5</AutoSaveInMinutes>
    <TotalPCU>1000000</TotalPCU>
    <EnableCopyPaste>false</EnableCopyPaste>
  </SessionSettings>
  <LoadWorld>/appdata/space-engineers/World</LoadWorld>
  <ServerName>SE Server</ServerName>
  <WorldName>Star System</WorldName>
  <Mods />
</MyConfigDedicated>
`;
const SE_WORLD_XML = `<?xml version="1.0"?>
<MyObjectBuilder_WorldConfiguration xmlns:xsd="http://www.w3.org/2001/XMLSchema">
  <Settings>
    <GameMode>Survival</GameMode>
    <MaxPlayers>8</MaxPlayers>
    <OnlineMode>FRIENDS</OnlineMode>
    <AutoSaveInMinutes>5</AutoSaveInMinutes>
  </Settings>
  <Mods />
</MyObjectBuilder_WorldConfiguration>
`;
const SE_G = (active = true) => guestFor("spaceengineers", { image: "mmmaxwwwell/space-engineers-dedicated-docker-linux:latest", files: { [SE_CFG]: SE_CFG_XML, [SE_WORLD_CONFIG]: SE_WORLD_XML }, active });
test("spaceengineers: xml helpers set only the named element, escape text, and detect broken XML", () => {
  assert.equal(xmlSetElement(SE_CFG_XML, "ServerName", "A & <B>")!.includes("<ServerName>A &amp; &lt;B&gt;</ServerName>"), true);
  assert.equal(xmlGetElement(xmlSetElement(SE_CFG_XML, "ServerName", "A & <B>")!, "ServerName"), "A & <B>");
  assert.equal(xmlSetElement(SE_CFG_XML, "MaxPlayers", "4", "SessionSettings")!.replace("<MaxPlayers>4<", "<MaxPlayers>16<"), SE_CFG_XML);
  assert.equal(xmlSetElement(SE_CFG_XML, "Nope", "1"), null);
  assert.equal(xmlSetElement(SE_CFG_XML, "MaxPlayers", "4", "Settings"), null, "scope must match the element name exactly");
  assert.ok(xmlSetElement("<R><ServerName /></R>", "ServerName", "x")!.includes("<ServerName>x</ServerName>"));
  assert.equal(xmlProblem(SE_CFG_XML), null);
  assert.ok(xmlProblem("<a><b></a>"));
});
test("spaceengineers: every field is written to the cfg (and the world file where the element exists); stop->patch->start", async () => {
  const cases: [string, string | number, string, string][] = [
    ["serverName", "Orbital Yard", "ServerName", "Orbital Yard"],
    ["gameMode", "Creative", "GameMode", "Creative"],
    ["maxPlayers", 24, "MaxPlayers", "24"],
    ["onlineMode", "PRIVATE", "OnlineMode", "PRIVATE"],
    ["environmentHostility", "CATACLYSM", "EnvironmentHostility", "CATACLYSM"],
    ["autoSaveInMinutes", 10, "AutoSaveInMinutes", "10"],
    ["totalPCU", 500000, "TotalPCU", "500000"],
  ];
  for (const [field, value, tag, expected] of cases) {
    const g = SE_G();
    const out = await run(spaceengineersApplier, g, defaults("spaceengineers", { [field]: value }), [field]);
    assert.equal(out.ok, true, `${field}: ${all(out)}`);
    const cfg = g.files.get(SE_CFG)!;
    assert.equal(xmlGetElement(cfg, tag, tag === "ServerName" ? undefined : "SessionSettings"), expected, field);
    assert.ok(cfg.includes("<EnableCopyPaste>false</EnableCopyPaste>") && cfg.includes("<WorldName>Star System</WorldName>") && cfg.includes("<Mods />"));
    if (tag !== "ServerName" && tag !== "TotalPCU") assert.equal(xmlGetElement(g.files.get(SE_WORLD_CONFIG)!, tag, "Settings"), expected, `${field} in world`);
    assert.equal(out.restarted, true);
    assert.ok(g.log.indexOf("systemctl stop 'spaceengineers.service'") < g.log.findIndex((l) => l.startsWith("write")));
  }
});
test("spaceengineers: worldName is saved only; missing element is reported not invented; no-op; stopped stays stopped", async () => {
  assert.equal("worldName" in SPACEENGINEERS_SPEC.fields, false);
  const g = SE_G();
  const out = await run(spaceengineersApplier, g, defaults("spaceengineers", { totalPCU: 123456 }), ["totalPCU"]);
  assert.match(all(out), /TotalPCU/);
  const noElem = guestFor("spaceengineers", { image: "x", files: { [SE_CFG]: SE_CFG_XML.replace("    <TotalPCU>1000000</TotalPCU>\n", "") } });
  const o2 = await run(spaceengineersApplier, noElem, defaults("spaceengineers", { totalPCU: 123456 }), ["totalPCU"]);
  assert.match(all(o2), /weren't found/);
  assert.ok(!noElem.log.some((l) => l.startsWith("systemctl stop")));
  const same = await run(spaceengineersApplier, SE_G(), defaults("spaceengineers", { serverName: "SE Server" }), ["serverName"]);
  assert.match(all(same), /already matched/);
  const stopped = SE_G(false);
  const o3 = await run(spaceengineersApplier, stopped, defaults("spaceengineers", { serverName: "Quiet" }), ["serverName"]);
  assert.equal(o3.ok, true);
  assert.equal(stopped.containers.get("spaceengineers")!.running, false);
});
test("spaceengineers: not-well-formed XML is refused and untouched; corrupted write rolls back", async () => {
  const g = guestFor("spaceengineers", { image: "x", files: { [SE_CFG]: "<a><b></a>" } });
  const out = await run(spaceengineersApplier, g, defaults("spaceengineers", { serverName: "Z" }), ["serverName"]);
  assert.equal(out.ok, false);
  assert.equal(g.files.get(SE_CFG), "<a><b></a>");
  const g2 = fakeGuest({ container: "spaceengineers", unit: "spaceengineers.service", files: { [SE_CFG]: SE_CFG_XML }, corruptWrite: SE_CFG });
  const o2 = await runApplier(spaceengineersApplier, { server: { id: "s" }, values: defaults("spaceengineers", { serverName: "Z" }), changed: ["serverName"], restartRequested: false, guest: g2.guest, unit: g2.unit, waitPort: async () => ({ ok: true }) });
  assert.equal(o2.ok, false);
  assert.equal(g2.files.get(SE_CFG), SE_CFG_XML);
});
